-- Phase B1 / 07: storage buckets and object policies.
-- id-documents / ownership-documents / contracts are private and only reachable
-- through short-lived signed URLs generated by server code. unit-photos is
-- public-read, but its paths still start with the unit UUID so they are hard to
-- enumerate by guessing.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  (
    'id-documents',
    'id-documents',
    false,
    5242880,
    array['image/jpeg', 'image/png', 'application/pdf']
  ),
  (
    'ownership-documents',
    'ownership-documents',
    false,
    5242880,
    array['image/jpeg', 'image/png', 'application/pdf']
  ),
  (
    'contracts',
    'contracts',
    false,
    10485760,
    array['application/pdf']
  ),
  (
    'unit-photos',
    'unit-photos',
    true,
    10485760,
    array['image/jpeg', 'image/png', 'image/webp']
  )
on conflict (id) do update
set public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

-- ---------------------------------------------------------------------------
-- id-documents: path = {user_id}/{filename}
-- ---------------------------------------------------------------------------
drop policy if exists "id_documents_select_own" on storage.objects;
create policy "id_documents_select_own"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'id-documents'
  and (storage.foldername(name))[1] = (select auth.uid())::text
);

drop policy if exists "id_documents_select_staff" on storage.objects;
create policy "id_documents_select_staff"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'id-documents'
  and (select private.is_leader_or_admin())
);

drop policy if exists "id_documents_insert_own_student" on storage.objects;
create policy "id_documents_insert_own_student"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'id-documents'
  and (storage.foldername(name))[1] = (select auth.uid())::text
  and (select private.has_role('student'::public.app_role))
);

drop policy if exists "id_documents_update_own_student" on storage.objects;
create policy "id_documents_update_own_student"
on storage.objects
for update
to authenticated
using (
  bucket_id = 'id-documents'
  and (storage.foldername(name))[1] = (select auth.uid())::text
  and (select private.has_role('student'::public.app_role))
)
with check (
  bucket_id = 'id-documents'
  and (storage.foldername(name))[1] = (select auth.uid())::text
  and (select private.has_role('student'::public.app_role))
);

