-- ---------------------------------------------------------------------------
-- unit-photos: path = {unit_id}/{filename}
-- Owners may upload/update/delete photos for their own units. Assigned team
-- members may upload inspection photos, but cannot delete owner photos.
-- ---------------------------------------------------------------------------
drop policy if exists "unit_photos_select_public" on storage.objects;
create policy "unit_photos_select_public"
on storage.objects
for select
to anon, authenticated
using (bucket_id = 'unit-photos');

drop policy if exists "unit_photos_insert_owner_or_team" on storage.objects;
create policy "unit_photos_insert_owner_or_team"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'unit-photos'
  and (
    exists (
      select 1
      from public.units as u
      where u.id::text = (storage.foldername(name))[1]
        and u.owner_id = (select auth.uid())
    )
    or exists (
      select 1
      from public.unit_visits as v
      where v.unit_id::text = (storage.foldername(name))[1]
        and v.team_member_id = (select auth.uid())
        and v.status in ('scheduled', 'completed')
    )
  )
);

drop policy if exists "unit_photos_update_owner" on storage.objects;
create policy "unit_photos_update_owner"
on storage.objects
for update
to authenticated
using (
  bucket_id = 'unit-photos'
  and exists (
    select 1
    from public.units as u
    where u.id::text = (storage.foldername(name))[1]
      and u.owner_id = (select auth.uid())
  )
)
with check (
  bucket_id = 'unit-photos'
  and exists (
    select 1
    from public.units as u
    where u.id::text = (storage.foldername(name))[1]
      and u.owner_id = (select auth.uid())
  )
);

drop policy if exists "unit_photos_delete_owner" on storage.objects;
create policy "unit_photos_delete_owner"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'unit-photos'
  and exists (
    select 1
    from public.units as u
    where u.id::text = (storage.foldername(name))[1]
      and u.owner_id = (select auth.uid())
  )
);

-- ---------------------------------------------------------------------------
-- contracts: path = {booking_id}/{filename} or external/{student_id}/{filename}
-- Uploads and status changes are server-only; parties may only download.
-- ---------------------------------------------------------------------------
drop policy if exists "contracts_select_parties" on storage.objects;
create policy "contracts_select_parties"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'contracts'
  and exists (
    select 1
    from public.contracts as c
    where c.file_path = name
      and (
        c.student_id = (select auth.uid())
        or c.owner_id = (select auth.uid())
      )
  )
);

drop policy if exists "contracts_select_staff" on storage.objects;
create policy "contracts_select_staff"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'contracts'
  and (select private.is_leader_or_admin())
);
